mapper.insert:
insert into TB_BMS_DISPOSAL
		(
		    DISPOSAL_ISSUE_DATE
		,  IN_NO
		,  CARGO_REFERENCE_NO
		,  BL_NO
		,  MBL_NO
		,  DISPOSAL_REASON
		,  DISPOSAL_CODE
		,  DISPOSAL_NAME
		,  CUSTOMER_CODE
		,  CUSTOMER_NAME
		,  CUSTOMER_TEL
		,  CUSTOMER_ADDRESS_1
		,  CUSTOMER_ADDRESS_2
		,  AMOUNT_USD
		,  DISPOSAL_LOC
		,  DISPOSAL_EXP_DATE
		,  DISPOSAL_METHOD
		,  DISPOSAL_FINISH_DATE
		,  PKG_TYPE
		,  DISPOSAL_CT
		,  DISPOSAL_WT
		,  OUT_YN
		,  REGISTER_USER_ID
		,  REGISTER_DATE_TIME
		,  UPDATE_USER_ID
		,  UPDATE_DATE_TIME
		)
values (
         CONVERT(DATE,  #{disposalIssueDate}, ${dateFormat})
	   , #{inNo}
	   , #{cargoReferenceNo}
	   , #{blNo}
	   , #{mblNo}
	   , #{disposalReason}
	   , #{disposalCode}
	   , #{disposalName}
	   , #{customerCode}
	   , #{customerName}
	   , dbo.Cryptography(#{cargoReferenceNo}, #{customerTel}, 0)
	   , #{customerAddress1}
	   , #{customerAddress2}
	   , #{amountUsd}
	   , #{disposalLoc}


				, CONVERT(DATE,  #{disposalExpDate}, ${dateFormat})


				,#{disposalExpDate}


	   , #{disposalMethod}


		 , CONVERT(DATE,  #{disposalFinishDate}, ${dateFormat})


		 ,#{disposalFinishDate}


	   , #{pkgType}
	   , #{disposalCt}
	   , #{disposalWt}
	   , 'N' -- 화면에서 입력시에는 N
	   , #{registerUserId}
	   ,  GETDATE()
	   , #{updateUserId}
	   , GETDATE()
	   )

mapper.update:
update TB_BMS_DISPOSAL
DISPOSAL_ISSUE_DATE = #{disposalIssueDate}, IN_NO = #{inNo}, CARGO_REFERENCE_NO = #{cargoReferenceNo}, BL_NO = #{blNo}, MBL_NO = #{mblNo}, DISPOSAL_REASON = #{disposalReason}, DISPOSAL_CODE = #{disposalCode}, DISPOSAL_NAME = #{disposalName}, CUSTOMER_CODE = #{customerCode}, CUSTOMER_NAME = #{customerName}, CUSTOMER_TEL = dbo.Cryptography(#{cargoReferenceNo}, #{customerTel}, 0), CUSTOMER_ADDRESS_1 = #{customerAddress1}, CUSTOMER_ADDRESS_2 = #{customerAddress2}, AMOUNT_USD = #{amountUsd}, DISPOSAL_LOC = #{disposalLoc}, DISPOSAL_EXP_DATE = #{disposalExpDate}, DISPOSAL_METHOD = #{disposalMethod}, DISPOSAL_FINISH_DATE = #{disposalFinishDate}, PKG_TYPE = #{pkgType}, DISPOSAL_CT = #{disposalCt}, DISPOSAL_WT = #{disposalWt}, UPDATE_DATE_TIME = GETDATE()
where DISPOSAL_NO = #{disposalNo}

mapper.select:
select TOP 1 DISPOSAL_NO , DISPOSAL_ISSUE_DATE , IN_NO , CARGO_REFERENCE_NO , BL_NO , MBL_NO , DISPOSAL_REASON , DISPOSAL_CODE , DISPOSAL_NAME , CUSTOMER_CODE , CUSTOMER_NAME , dbo.Cryptography(CARGO_REFERENCE_NO, CUSTOMER_TEL, 1) AS CUSTOMER_TEL , CUSTOMER_ADDRESS_1 , CUSTOMER_ADDRESS_2 , AMOUNT_USD , DISPOSAL_LOC , DISPOSAL_EXP_DATE , DISPOSAL_METHOD , DISPOSAL_FINISH_DATE , PKG_TYPE , DISPOSAL_CT , DISPOSAL_WT , OUT_YN , REGISTER_USER_ID , REGISTER_DATE_TIME , UPDATE_USER_ID , UPDATE_DATE_TIME , (SELECT USER_NAME FROM TB_SMS_USER WHERE USER_ID = A.REGISTER_USER_ID) AS REGISTER_USER_NAME , (SELECT USER_NAME FROM TB_SMS_USER WHERE USER_ID = A.UPDATE_USER_ID) AS UPDATE_USER_NAME FROM TB_BMS_DISPOSAL A where (1=1)
AND DISPOSAL_NO = #{srchDisposalNo}
AND IN_NO = #{srchInNo}
AND CARGO_REFERENCE_NO = #{cargoReferenceNo}
ORDER BY DISPOSAL_NO DESC

