mapper.insert:
INSERT INTO TB_BMS_OUT ( CUSTOMS_REPORT_NO , LAST_POD_DATE , LAST_POD_STATUS , LAST_POD_RAQ_DATE , APPROVAL_DATE , OUT_CLASS , OUT_APPROVAL_NO , OD_JOB_NO , IN_NO , OUT_PLAN_NO , CARGO_REFERENCE_NO , BL_NO , MBL_NO , DO_NO , DO_DATE , CUSTOMS_CODE , CUSTOMS_DPT_CODE , CUSTOMER_CODE , CUSTOMER_NAME , BROKER_CODE , BROKER_NAME , PKG_TYPE , APPROVAL_CT , APPROVAL_WT , APPROVAL_CBM , OUT_CT , OUT_WT , OUT_CBM , CARRYOUT_DATE , CARRYOUT_TIME , APPROVAL_DUTY , APPROVAL_APPRAISE_VALUE , INS_PAYMENT_TYPE , CURRENCY_CODE , INS_PAYMENT_YN , INSPECT_YN , HS_CODE , CRITERIA_CODE , INOUT_DATE_DIFF , REMARKS_1 , REMARKS_2 , REMARKS_3 , REFERENCE_NO , REGISTER_USER_ID , REGISTER_DATE_TIME , UPDATE_USER_ID , UPDATE_DATE_TIME ) SELECT #{customsReportNo} AS CUSTOMS_REPORT_NO , '' LAST_POD_DATE , 'BMS01' LAST_POD_STATUS , '' LAST_POD_RAQ_DATE , CONVERT(VARCHAR(10),GETDATE(),120) AS APPROVAL_DATE , '83' OUT_CLASS , '' OUT_APPROVAL_NO , tbi.OD_JOB_NO , tbi.IN_NO , '' OUT_PLAN_NO , tbi.CARGO_REFERENCE_NO , tbi.BL_NO , tbi.MBL_NO , '' DO_NO , '' DO_DATE , tbi.CUSTOMS_CODE , tbi.CUSTOMS_DPT_CODE , tbi.CUSTOMER_CODE , tbi.CUSTOMER_NAME , '' BROKER_CODE , '' BROKER_NAME , tbi.PKG_TYPE , tbd.DISPOSAL_CT APPROVAL_CT , tbd.DISPOSAL_WT APPROVAL_WT , (CASE WHEN tbi.CBM=0 THEN 0 WHEN tbi.WT=tbd.DISPOSAL_WT THEN tbi.CBM WHEN tbi.WT =0 THEN 0 ELSE ROUND(tbi.CBM * (tbd.DISPOSAL_WT/tbi.WT),3) END) APPROVAL_CBM , tbd.DISPOSAL_CT OUT_CT , tbd.DISPOSAL_WT OUT_WT , (CASE WHEN tbi.CBM=0 THEN 0 WHEN tbi.WT=tbd.DISPOSAL_WT THEN tbi.CBM WHEN tbi.WT =0 THEN 0 ELSE ROUND(tbi.CBM * (tbd.DISPOSAL_WT/tbi.WT),3) END) OUT_CBM , CONVERT(VARCHAR(10),GETDATE(),120) CARRYOUT_DATE /* 현재 날자 10자리 */ , CONVERT(CHAR(8), GETDATE(), 108) CARRYOUT_TIME /*현재 시간 8자리*/ , 0 APPROVAL_DUTY , 0 APPROVAL_APPRAISE_VALUE , '' INS_PAYMENT_TYPE , '' CURRENCY_CODE , 'N' INS_PAYMENT_YN , 'N' INSPECT_YN , '' HS_CODE , '' CRITERIA_CODE , dbo.GET_DATE_DIFF_KOR_STR(concat(tbi.CARRYIN_DATE,' ',tbi.CARRYIN_TIME )) INOUT_DATE_DIFF , '' REMARKS_1 , '' REMARKS_2 , '' REMARKS_3 , tbi.REFERENCE_NO , #{registerUserId} REGISTER_USER_ID , GETDATE() REGISTER_DATE_TIME , #{updateUserId} UPDATE_USER_ID , GETDATE() UPDATE_DATE_TIME FROM TB_BMS_DISPOSAL tbd LEFT JOIN TB_BMS_IN tbi WITH (NOLOCK) ON tbd.IN_NO = tbi.IN_NO LEFT JOIN TB_SMS_CUSTOMER tsc ON tbd.CUSTOMER_CODE = tsc.CUSTOMER_CODE where tbd.DISPOSAL_NO = #{disposalNo} ;
DECLARE @v_OD_JOB_NO VARCHAR(24); DECLARE @v_POD_NAME NVARCHAR(100); DECLARE @v_POD_DATE VARCHAR(10); DECLARE @v_POD_TIME VARCHAR(8); DECLARE @v_REMARKS NVARCHAR(200);
SET @v_POD_TIME = SUBSTRING(CONVERT(VARCHAR(10), GETDATE(), 108), 1, 8); SET @v_REMARKS = '';
SET @v_POD_NAME = N'체화폐기반출(일괄)';
SELECT @v_OD_JOB_NO = tbi.OD_JOB_NO FROM TB_BMS_DISPOSAL tbd LEFT JOIN TB_BMS_IN tbi WITH (NOLOCK) ON tbd.IN_NO = tbi.IN_NO where tbd.DISPOSAL_NO = #{disposalNo} ;
/* POD multi data */ INSERT INTO TB_ECM_POD_05 ( ENT_CODE , OD_JOB_NO , POD_STATUS , POD_NAME , POD_DATE , POD_TIME, REMARKS , REGISTER_USER_ID, REGISTER_DATE_TIME , UPDATE_USER_ID, UPDATE_DATE_TIME ) SELECT #{entCode} , @v_OD_JOB_NO , 'ECM288', @v_POD_NAME, GETDATE() , @v_POD_TIME, ISNULL(@v_REMARKS,'') , 'DAEMON', GETDATE() , 'DAEMON', GETDATE() ;

